#!/bin/sh

cd "$(dirname "$0")" || exit 1

APPID="NTXS00053"
CONTENTID="UP0001-"$APPID"_00-0000000000000000"

rm -Rf pkg
mkdir -p pkg/USRDIR/gfx

cp ICON0.PNG pkg
if [ -f PIC1.PNG ]; then cp PIC1.PNG pkg; else cp ICON0.PNG pkg/PIC1.PNG; fi

# Copy the full romfs (gfx + any bundled project) if it was generated by the build.
if [ -d ../../romfs ]; then
    cp -r ../../romfs/* pkg/USRDIR/
fi

sprxlinker ../../build-ps3/scratch-ps3.elf
make_self_npdrm ../../build-ps3/scratch-ps3.elf pkg/USRDIR/EBOOT.BIN $CONTENTID

sfo --fromxml sfo.xml pkg/PARAM.SFO
pkg --contentid=$CONTENTID pkg/ SE.pkg

rm -Rf pkg